// Normalizes a Sheet1 row (S.No, Company, Website, LinkedIn, Industry, Annual Revenue, DM Name,
// DM Email, DM_Phone, DM Title, DM LinkedIn, Buying Signals, Signal Count) into internal field names.
const src = $json.body || $json;
const s = v => (v == null ? '' : v).toString().trim();
return { json: {
  s_no: s(src['S.No']),
  company: s(src['Company']),
  website: s(src['Website']),
  linkedin: s(src['LinkedIn']),
  industry: s(src['Industry']),
  annual_revenue: s(src['Annual Revenue']),
  dm_name: s(src['DM Name']),
  dm_email: s(src['DM Email']).toLowerCase(),
  dm_phone: s(src['DM_Phone'] || src['DM Mobile']),
  dm_title: s(src['DM Title']),
  dm_linkedin: s(src['DM LinkedIn']),
  buying_signals: s(src['Buying Signals']),
  signal_count: Number(src['Signal Count']) || 0,
  country: s(src['Country']),      // optional column; helps with numbers typed without +countrycode
  timezone: s(src['Timezone'])     // optional column; IANA name e.g. Asia/Kolkata, overrides auto-detection
}};

for (const i of $input.all()) {
  console.warn(`[INTAKE SKIP] no DM_Phone for company="${i.json.company}" s_no=${i.json.s_no}`);
}
return $input.all();

// Extracts the identifiers + transcript. to_number = the lead (from_number/phone_number is our caller ID).
const body = $json.body || $json;
function normalize(raw) {
  let digits = (raw == null ? '' : raw).toString().replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length > 15) { // repair duplicated country-code prefixes, e.g. 9191...
    for (let codeLen = 3; codeLen >= 1; codeLen--) {
      const prefix = digits.slice(0, codeLen), nextBlock = digits.slice(codeLen, codeLen * 2);
      const remainderLen = digits.length - codeLen * 2;
      if (prefix === nextBlock && remainderLen >= 7 && remainderLen <= 12) {
        const candidate = digits.slice(codeLen);
        if (candidate.length <= 15) { digits = candidate; break; }
      }
    }
  }
  return '+' + digits;
}
let transcript = body.call_report && body.call_report.full_conversation;
if (Array.isArray(transcript)) {
  transcript = transcript.map(t => typeof t === 'string' ? t
    : `${t.role || t.speaker || ''}: ${t.content || t.text || t.message || ''}`).join('\n');
} else if (transcript && typeof transcript === 'object') {
  transcript = JSON.stringify(transcript);
}
transcript = (transcript || '').toString().slice(0, 30000);
// Deterministic Do-Not-Call detection. Over-suppression is the safe failure mode.
const DNC_RE = /\b(do\s*not\s*call|don'?t\s*(ever\s*)?call|stop\s*calling|remove\s*(me|us|my\s*number)|take\s*(me|us|my\s*number)\s*off|never\s*call|unsubscribe)\b/i;
return { json: {
  call_id: body.call_id != null && body.call_id !== '' ? String(body.call_id).trim() : '',
  to_number: normalize(body.to_number),
  transcript,
  dnc_keyword: DNC_RE.test(transcript),
  raw: body
}};

// Match by Call ID (written at dispatch). Fallback: newest IN-FLIGHT row with the same phone.
// Only rows still Dispatched/Dispatching are processed -> duplicate or late webhooks are ignored
// (this is what makes post-call processing idempotent).
const call = $('Parse Post-Call Payload').first().json;
const digits = v => (v == null ? '' : v).toString().replace(/\D/g, '');
const IN_FLIGHT = ['Dispatched', 'Dispatching'];
const rows = $input.all().map(i => i.json).filter(r => r && r.row_number);
let row = null, matched_by = '';
if (call.call_id) {
  row = rows.find(r => (r['Call ID'] == null ? '' : r['Call ID']).toString().trim() === call.call_id) || null;
  if (row) matched_by = 'call_id';
}
if (!row && call.to_number) {
  const target = digits(call.to_number);
  const cands = rows.filter(r => digits(r['Phone Number']) === target
    && IN_FLIGHT.includes((r['Call Status'] || '').toString().trim()));
  if (cands.length) { row = cands[cands.length - 1]; matched_by = 'phone_in_flight'; }
}
const current_status = row ? (row['Call Status'] || '').toString().trim() : '';
const should_process = !!row && IN_FLIGHT.includes(current_status);
return [{ json: {
  ...call, should_process, matched_by, current_status,
  row_number: row ? row.row_number : null,
  company: row ? (row['Company'] || '') : '',
  dm_name: row ? (row['DM Name'] || '') : '',
  dm_title: row ? (row['DM Title'] || '') : '',
  dm_email: row ? (row['DM Email'] || '') : '',
  phone_number_stored: row ? (row['Phone Number'] || '') : '',
  timezone: row ? (row['Timezone'] || '') : '',
  retry_count: row ? (parseInt(row['Retry Count'], 10) || 0) : 0
}}];

for (const i of $input.all()) {
  const j = i.json;
  console.warn(`[WEBHOOK IGNORED] call_id=${j.call_id || ''} to=${(j.to_number || '').slice(-4)} ` +
    `matched_by=${j.matched_by || 'none'} status="${j.current_status || ''}" ` +
    `(unknown call, duplicate, or already processed)`);
}
return $input.all();

